    [19845]={name="Zandalar Illusionist's Mantle",quality=4,ilvl=61,sourceType="quest_reward",instructions="Reward from the quest 'Paragons of Power: The Illusionist's Mantle'.",zone="Zul'Gurub",questName="Paragons of Power: The Illusionist's Mantle",lore="How can one truly hope to win against a foe that is not even really there? We Zandalar know the power of this, and as such illusionists hold a honored place within the tribe."},
    [19846]={name="Zandalar Illusionist's Wraps",quality=4,ilvl=61,sourceType="quest_reward",instructions="Reward from the quest 'Paragons of Power: The Illusionist's Wraps'.",zone="Zul'Gurub",questName="Paragons of Power: The Illusionist's Wraps",lore="For you to know the way of our illusionists, go to Zul'Gurub and bring back to me selected Paragons of Power. For this, I will give you arm wraps our illusionists use to weave their spells."},
