    [20641]={name="Southsea Mojo Boots",quality=2,ilvl=45,sourceType="quest_reward",instructions="Reward from the quest 'Southsea Shakedown'. Pick it over the other reward choices.",zone="Tanaris",questName="Southsea Shakedown",lore="They want the impossible from me! The Steamwheedle Cartel wants me to teach the Southsea pirates a lesson."},
    [20724]={name="Corrupted Blackwood Staff",quality=2,ilvl=62,sourceType="quest_reward",instructions="Reward from the quest 'Into The Maw of Madness'.",zone="Silithus",questName="Into The Maw of Madness",lore="I need you to venture into Hive'Regal and find what became of my dearest Natalia. This will be no easy task for you. Before you dive headlong into the maw of madness, make sure that you go back and speak with those dwarves."},
