    [22589]={name="Atiesh, Greatstaff of the Guardian",quality=5,ilvl=90,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Atiesh, Greatstaff of the Guardian'.",questName="Atiesh, Greatstaff of the Guardian",lore="The Guardian's staff, broken and scattered. Rebuilding it means gathering forty splinters from Naxxramas, the base from Kel'Thuzad, and carrying it to the ruin of Karazhan where Medivh once held it.",proc="Use: Creates a portal, teleporting group members that use it to Karazhan. (1 Min Cooldown)"},
    [22657]={name="Amulet of the Dawn",quality=4,ilvl=60,sourceType="quest_reward",instructions="Reward from the quest 'Epic Armaments of Battle - Friend of the Dawn'. Pick it over the other reward choices.",zone="Eastern Plaguelands",questName="Epic Armaments of Battle - Friend of the Dawn",lore="Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of great power?"},
    [22667]={name="Bracers of Hope",quality=4,ilvl=60,sourceType="quest_reward",instructions="Reward from the quest 'Epic Armaments of Battle - Friend of the Dawn'. Pick it over the other reward choices.",zone="Eastern Plaguelands",questName="Epic Armaments of Battle - Friend of the Dawn",lore="Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of great power? I must warn you; purchases made at a friendly reputation with the Dawn come with an extremely hefty surcharge."},
    [22954]={name="Kiss of the Spider",quality=4,ilvl=85,reqLevel=60,sourceType="boss_drop",instructions="Drops from Maexxna.",zone="Naxxramas",npc="Maexxna",lore="A giant spider webbed into the depths of the Arachnid Quarter, fed on whatever the Scourge no longer needs.",proc="Use: Increases your haste rating by 200 for 15 sec. (2 Min Cooldown)"},
    [23001]={name="Eye of Diminution",quality=4,ilvl=85,reqLevel=60,sourceType="boss_drop",instructions="Drops from Thaddius.",zone="Naxxramas",npc="Thaddius",lore="Two abominations sewn into one and animated with stolen lightning -- one of Kel'Thuzad's more ambitious experiments in the Construct Quarter.",proc="Use: Reduces the threat you generate by [35 - max(0, Level - 60)]% for 20 sec. (2 Min Cooldown)"},
    [23031]={name="Band of the Inevitable",quality=4,ilvl=83,reqLevel=60,sourceType="boss_drop",instructions="Drops from Noth the Plaguebringer.",zone="Naxxramas",npc="Noth the Plaguebringer",lore="A necromancer of the Plague Quarter, promoted for his skill at raising what he had just finished killing."},
    [23046]={name="The Restrained Essence of Sapphiron",quality=4,ilvl=90,reqLevel=60,sourceType="boss_drop",instructions="Drops from Sapphiron.",npc="Sapphiron",lore="A blue dragon slain in Northrend and raised as a frost wyrm. He guards the final approach to Kel'Thuzad's chamber.",proc="Use: Increases damage and healing done by magical spells and effects by up to 130 for 20 sec. (2 Min Cooldown)"},
    [23057]={name="Gem of Trapped Innocents",quality=4,ilvl=92,reqLevel=60,sourceType="boss_drop",instructions="Drops from Kel'Thuzad.",zone="Naxxramas",npc="Kel'Thuzad",lore="Once an archmage of the Kirin Tor, he left Dalaran to found the Cult of the Damned and served Ner'zhul willingly. Killed at Andorhal and raised as a lich, he rules Naxxramas from a phylactery at its heart."},
    [23062]={name="Frostfire Ring",quality=4,ilvl=92,reqLevel=60,sourceType="boss_drop",instructions="Drops from Kel'Thuzad.",zone="Naxxramas",npc="Kel'Thuzad",lore="Once an archmage of the Kirin Tor, he left Dalaran to found the Cult of the Damned and served Ner'zhul willingly. Killed at Andorhal and raised as a lich, he rules Naxxramas from a phylactery at its heart."},
